/**
 * @method
 * @name ins_search
 * @description 신주인수권 표준코드관리  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    /*if( (txb_pSTD_CD.value =="" || txb_pSTD_CD.value.indexOf(" ") == "" )
    	&& (txb_pISU_NM.value =="" || txb_pISU_NM.value.indexOf(" ") == "" )
    	&& (txb_pISUR_CD.value =="" || txb_pISUR_CD.value.indexOf(" ") == "" )
    	&& (edt_pSTD_CD_GRNT_DD_SDATE.text =="" || edt_pSTD_CD_GRNT_DD_SDATE.text.indexOf(" ") == "" )
    	&& (edt_pSTD_CD_GRNT_DD_EDATE.text =="" || edt_pSTD_CD_GRNT_DD_EDATE.text.indexOf(" ") == "" )  ){
    		alert( "조회 파라메터가 부족합니다" );
    		return;
    }*/

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE) === false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) === false) {
        return false;
    }

    // 데이터셋 초기화
    dts_List.removeAll();
    dts_detail.removeAll();

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
     * @method
     * @name ins_detail
     * @description 신주인수권 표준코드관리 상세 조회한다.
     * @param {String} STD_CD STD_CD
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.ins_detail = async function(STD_CD) {
    // 데이터셋 초기화
    dts_detail.removeAll();

    // 수익증권 표준코드관리
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_modify
 * @description 신주인수권 표준코드관리 저장 , 수정 한다. screenProcsTpCd 02,03
 * @param {String} mflag mflag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_modify = async function(mflag) {
    let screenProcsTpCd = "03";
    if (screenProcsTpCd === '03') {
        // 수정

        if (!$c.cp.isModified(dts_detail)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }

        // alert( txb_ISU_NM.getAttribute("Maxlength") );

        if (txb_STD_CD.getValue() === "" || txb_STD_CD.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "표준코드"));
            txb_STD_CD.focus();
            return;
        }
        if (!$c.stf.checkMaxLength(txb_STD_CD, 12, "표준코드")) {
            txb_STD_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() === "" || txb_ISU_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_ISU_ABBRV.getValue() === "" || txb_ISU_ABBRV.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
            txb_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
            // txb_ISU_ENG_ABBRV.value = "";
            txa_NUSUAL_ISU_COND_CONTN.focus();
            return false;
        }

        // CFI체크
        if (cmb_cb_p_group.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
            cmb_cb_p_group.focus();
            return false;
        }
        if (cmb_cb_p_attr_1.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
            cmb_cb_p_attr_1.focus();
            return false;
        }
        if (cmb_cb_p_attr_2.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
            cmb_cb_p_attr_2.focus();
            return false;
        }
        if (cmb_cb_p_attr_3.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
            cmb_cb_p_attr_3.focus();
            return false;
        }
        if (cmb_cb_p_attr_4.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
            cmb_cb_p_attr_4.focus();
            return false;
        }
        if (mflag === "N") return;
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/StdCdBwInfoAction.do",
            ref : "dts_detail",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name changeCfi
 * @description 증서증권 cfi 변경 설정
 * @returns {void}
 * @hidden N
 */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    cfi = "R";
    if (cmb_cb_p_group.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_group.getValue();
    if (cmb_cb_p_attr_1.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_1.getValue();
    if (cmb_cb_p_attr_2.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_2.getValue();
    if (cmb_cb_p_attr_3.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_3.getValue();
    if (cmb_cb_p_attr_4.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_4.getValue();
    txb_CFI_CD.setValue(cfi); // cfi 설정

};

/**
 * @method
 * @name set_Change
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi str_cfi
 * @returns {void}
 * @hidden N
 */
scwin.set_Change = function(str_cfi) {
    if (str_cfi === "") return;
    let temp = str_cfi.substring(0, 2);
    ins_cfi_set(dts_cfi_group, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, "04", "R", "", "", "G");
    ins_cfi_set(dts_cfi_group_1, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, "05", "R", "", "", "G");

    // 하나의 데이터셋으로 합치기
    dts_cfi_group.setBroadcast(false);
    for (let i = 2; i < dts_cfi_group_1.getRowCount() + 1; i++) {
        dts_cfi_group.insertRow();
        dts_cfi_group.setCellData(dts_cfi_group.getRowCount(), "VALUE", dts_cfi_group_1.getCellData(i, "VALUE"));
        dts_cfi_group.setCellData(dts_cfi_group.getRowCount(), "TEXT", dts_cfi_group_1.getCellData(i, "TEXT"));
    }
    dts_cfi_group.setBroadcast(true, true);
    cmb_cb_p_group.setValue(str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};

/**
 * @method
 * @name ins_remove
 * @description 표준코드 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_remove = async function() {
    let screenProcsTpCd = "04";
    // dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD"));
    dts_Delete.setCellData(1, "ISU_NM", dts_detail.getCellData(dts_detail.getRowPosition(), "ISU_NM"));
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_Delete.KeyName = "toinb_dataid4";
    // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Delete",
        action : "/StdCdBwInfoAction.do",
        ref : "dts_Delete",
        target : "trs_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**********************************************
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();

/**
