/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    // PanelToGroupBox(panel_6);

    txb_pSTD_CD.setValue("KRA");
    ins_combo_set(dts_BND_STKCERT_TP_CD, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, "03441", "SEL");
    ins_combo_set(dts_DOM_FORN_ISU_TP_CD, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, "03407", "SEL");
    ins_combo_set(dts_CURR_TP_CD, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, "02475", "SEL");
    ins_combo_set(dts_LIST_STAT_CD, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, "00714"); // 00714 -LIST_STAT_CD
    ins_combo_set(dts_STD_CD_APCT_TP_CD, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, "03527"); // 03527 - 신청자구분
    fn_CtrlBtn_temp("no_data");

    // cfi콤보셋팅
    // ins_cfi_set(dts_cfi_group, vScrenID, SCREN_PROCS_TP_CD_01, "04", "R", "", "", "G");

    txb_OBJ_STK_ISU_CD.hide();
    txb_OBJ_BND_ISU_CD.hide();
    txb_DEL_RSN.hide();
    txb_param1.hide();
    txb_param2.hide();
    txa_REF_CONTN.hide();

    // 2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------
    btn_clearPwd.hide();
    // 2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------

    const arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (let i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_pSTD_CD.focus();
};

