/**
 * @method
 * @name cmb_cb_p_group_onselchange
 * @description cmb_cb_p_group onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_group_onselchange = function() {
    if (cmb_cb_p_group.getValue() !== "") {
        let temp = cmb_BND_STKCERT_TP_CD.getValue(); // 금융상품구분 R:증서, WR:증권
        let temp2 = "";
        if (temp === "1") {
            // WR증권
            temp2 = "04";
        } else if (temp === "2") {
            // R증서
            temp2 = "05";
        }
        ins_cfi_set(dts_cfi_attr1, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, temp2, "R", cmb_cb_p_group.getValue(), "1", "");
        ins_cfi_set(dts_cfi_attr2, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, temp2, "R", cmb_cb_p_group.getValue(), "2", "");
        ins_cfi_set(dts_cfi_attr3, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, temp2, "R", cmb_cb_p_group.getValue(), "3", "");
        ins_cfi_set(dts_cfi_attr4, "ULDINS15700.xml", SCREN_PROCS_TP_CD_01, temp2, "R", cmb_cb_p_group.getValue(), "4", "");
        // alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
        label_attr1.setValue("(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
        label_attr2.setValue("(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
        label_attr3.setValue("(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
        label_attr4.setValue("(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
    }
    scwin.changeCfi();
};

